"use strict";
const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "KnowSelf: Teaching LLM Agents When to Think, Reflect, or Seek Knowledge";

// ── Color palette (Ocean/Midnight) ──────────────────────────────────────────
const C = {
  dark:    "0D1B2A",  // near-black navy – title/closing slides
  navy:    "1B3A5C",  // medium navy – section headers, cards
  teal:    "0D9488",  // teal accent
  tealLt:  "14B8A6",  // lighter teal
  mint:    "CCFBF1",  // very light mint – tinted areas
  white:   "FFFFFF",
  offWhite:"F8FAFC",
  lightBg: "EFF6FF",  // pale blue content bg
  slate:   "64748B",  // muted text
  dark2:   "1E293B",  // body text
  gold:    "F59E0B",  // highlight accent
  goldLt:  "FEF9C3",  // light gold bg
};

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.10 });

// ── Helper: slide title bar ─────────────────────────────────────────────────
function addTitle(slide, text, bg) {
  // Top bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.72,
    fill: { color: bg || C.navy }, line: { color: bg || C.navy }
  });
  slide.addText(text, {
    x: 0.4, y: 0, w: 9.2, h: 0.72,
    fontSize: 22, bold: true, color: C.white,
    valign: "middle", margin: 0
  });
}

// ── Helper: content footer ───────────────────────────────────────────────────
function addFooter(slide) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.45, w: 10, h: 0.175,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  slide.addText("KnowSelf  ·  arxiv.org/abs/2504.03553", {
    x: 0.4, y: 5.44, w: 9, h: 0.18,
    fontSize: 9, color: C.white, valign: "middle", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 1: Title
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.dark };

  // Large teal left accent bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.18, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal }
  });

  // Main title
  s.addText("KnowSelf", {
    x: 0.5, y: 0.7, w: 9, h: 1.1,
    fontSize: 52, bold: true, color: C.white,
    fontFace: "Calibri"
  });
  s.addText("Agentic Knowledgeable Self-Awareness\nfor LLM-Based Agents", {
    x: 0.5, y: 1.75, w: 8.5, h: 1.0,
    fontSize: 22, color: C.tealLt, bold: false,
    fontFace: "Calibri"
  });

  // Tagline card
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.0, w: 9.0, h: 1.1,
    fill: { color: C.navy }, line: { color: C.teal, width: 1.5 }
  });
  s.addText("Enabling agents to autonomously decide when to act directly,\nself-reflect, or consult external knowledge — only when needed.", {
    x: 0.65, y: 3.05, w: 8.7, h: 1.0,
    fontSize: 14, color: C.mint, italic: true, valign: "middle", margin: 0
  });

  // Reference
  s.addText("arxiv.org/abs/2504.03553", {
    x: 0.5, y: 4.3, w: 4, h: 0.3,
    fontSize: 11, color: C.slate
  });

  // Bottom teal bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.45, w: 10, h: 0.175,
    fill: { color: C.teal }, line: { color: C.teal }
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 2: Problem – Flood Irrigation
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  addTitle(s, "Current Agent Training Uses 'Flood Irrigation' — Indiscriminate Knowledge Injection");
  addFooter(s);

  // Three paradigm cards
  const cards = [
    { label: "Trajectory Imitation", sub: "ReAct-style", desc: "Blindly mimics gold trajectories. Fragile on unexpected inputs.", icon: "①" },
    { label: "Trial-and-Error", sub: "Reflexion-style", desc: "External feedback injected indiscriminately every step.", icon: "②" },
    { label: "Knowledge-Augmented", sub: "KnowAgent / WKM", desc: "Domain knowledge always prepended — 100% of the time.", icon: "③" },
  ];

  cards.forEach((c, i) => {
    const x = 0.35 + i * 3.1;
    s.addShape(pres.shapes.RECTANGLE, {
      x, y: 0.9, w: 2.9, h: 2.0,
      fill: { color: C.lightBg }, line: { color: C.navy, width: 1 },
      shadow: makeShadow()
    });
    // Accent top
    s.addShape(pres.shapes.RECTANGLE, {
      x, y: 0.9, w: 2.9, h: 0.12,
      fill: { color: C.navy }, line: { color: C.navy }
    });
    s.addText(c.icon + "  " + c.label, {
      x: x + 0.1, y: 1.02, w: 2.7, h: 0.35,
      fontSize: 13, bold: true, color: C.dark2, margin: 0
    });
    s.addText(c.sub, {
      x: x + 0.1, y: 1.36, w: 2.7, h: 0.25,
      fontSize: 11, color: C.teal, italic: true, margin: 0
    });
    s.addText(c.desc, {
      x: x + 0.1, y: 1.63, w: 2.7, h: 1.0,
      fontSize: 11, color: C.dark2, margin: 0
    });
  });

  // Arrow down to "Result"
  s.addShape(pres.shapes.LINE, {
    x: 5, y: 2.94, w: 0, h: 0.4,
    line: { color: C.slate, width: 1.5, dashType: "dash" }
  });

  // Result banner
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.35, y: 3.35, w: 9.3, h: 0.65,
    fill: { color: C.goldLt }, line: { color: C.gold, width: 1.5 }
  });
  s.addText("Result: Wasteful inference, pattern collapse, and suboptimal performance on novel inputs.", {
    x: 0.5, y: 3.38, w: 9.0, h: 0.58,
    fontSize: 13, bold: true, color: "92400E", valign: "middle", margin: 0
  });

  // Human contrast
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.35, y: 4.12, w: 9.3, h: 0.88,
    fill: { color: C.mint }, line: { color: C.teal, width: 1 }
  });
  s.addText("Humans use situational self-awareness — assessing whether to act directly, pause and reflect, or seek outside help. KnowSelf brings this metacognitive ability to LLM agents.", {
    x: 0.5, y: 4.15, w: 9.0, h: 0.82,
    fontSize: 12.5, color: C.dark2, valign: "middle", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 3: Three Thinking Modes – Flow Diagram
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  addTitle(s, "Three Situational Modes: Fast Thinking, Slow Thinking, and Knowledgeable Thinking", C.dark);
  addFooter(s);

  // Decision start node
  const nodeW = 2.4, nodeH = 0.52;
  function diamond(slide, x, y, w, h, fillColor, text, textColor) {
    // Draw as rotated rectangle visual using plain rect + label
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w, h,
      fill: { color: fillColor }, line: { color: C.navy, width: 1.2 }
    });
    slide.addText(text, {
      x, y, w, h,
      fontSize: 12, bold: true, color: textColor || C.white,
      align: "center", valign: "middle", margin: 0
    });
  }

  function outcome(slide, x, y, title, token, desc, fillColor) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: nodeW, h: 1.45,
      fill: { color: fillColor }, line: { color: C.navy, width: 1 },
      shadow: makeShadow()
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: nodeW, h: 0.1,
      fill: { color: C.navy }, line: { color: C.navy }
    });
    slide.addText(title, {
      x: x + 0.1, y: y + 0.1, w: nodeW - 0.2, h: 0.38,
      fontSize: 13, bold: true, color: C.dark2, margin: 0
    });
    slide.addText("Token: " + token, {
      x: x + 0.1, y: y + 0.48, w: nodeW - 0.2, h: 0.28,
      fontSize: 11, color: C.teal, italic: true, bold: true, margin: 0
    });
    slide.addText(desc, {
      x: x + 0.1, y: y + 0.76, w: nodeW - 0.2, h: 0.62,
      fontSize: 10.5, color: C.dark2, margin: 0
    });
  }

  // Start: Agent at a decision step
  diamond(s, 3.8, 0.85, 2.4, 0.52, C.navy, "Agent at Decision Step");

  // Arrow down
  s.addShape(pres.shapes.LINE, { x: 5.0, y: 1.37, w: 0, h: 0.35, line: { color: C.slate, width: 1.5 } });

  // Q1 diamond
  diamond(s, 3.3, 1.72, 3.4, 0.52, C.teal, "Predicted action = Gold?");

  // YES → left, NO → right
  s.addText("YES", { x: 1.7, y: 1.85, w: 0.7, h: 0.25, fontSize: 10, color: C.teal, bold: true, margin: 0 });
  s.addShape(pres.shapes.LINE, { x: 3.3, y: 1.98, w: -0.9, h: 0, line: { color: C.teal, width: 1.5 } }); // left
  s.addShape(pres.shapes.LINE, { x: 2.4, y: 1.98, w: 0, h: 1.1, line: { color: C.teal, width: 1.5 } }); // down

  s.addText("NO", { x: 7.0, y: 1.85, w: 0.5, h: 0.25, fontSize: 10, color: C.slate, bold: true, margin: 0 });
  s.addShape(pres.shapes.LINE, { x: 6.7, y: 1.98, w: 0.9, h: 0, line: { color: C.slate, width: 1.5 } }); // right
  s.addShape(pres.shapes.LINE, { x: 7.6, y: 1.98, w: 0, h: 0.35, line: { color: C.slate, width: 1.5 } }); // down

  // Fast thinking outcome (left)
  outcome(s, 1.2, 3.08, "Fast Thinking", "<FAST>", "Direct correct action — no extra computation needed.", "E0F2FE");

  // Q2 – reflection helps?
  diamond(s, 6.3, 2.33, 3.1, 0.52, C.slate, "Reflection fixes it?");

  s.addText("YES", { x: 5.5, y: 2.9, w: 0.7, h: 0.25, fontSize: 10, color: C.tealLt, bold: true, margin: 0 });
  s.addShape(pres.shapes.LINE, { x: 6.3, y: 2.59, w: -0.85, h: 0, line: { color: C.tealLt, width: 1.5 } });
  s.addShape(pres.shapes.LINE, { x: 5.45, y: 2.59, w: 0, h: 0.6, line: { color: C.tealLt, width: 1.5 } });

  s.addText("NO", { x: 9.55, y: 2.9, w: 0.5, h: 0.25, fontSize: 10, color: C.gold, bold: true, margin: 0 });
  s.addShape(pres.shapes.LINE, { x: 9.4, y: 2.59, w: 0.55, h: 0, line: { color: C.gold, width: 1.5 } });
  s.addShape(pres.shapes.LINE, { x: 9.95, y: 2.59, w: 0, h: 0.6, line: { color: C.gold, width: 1.5 } });

  // Slow thinking
  outcome(s, 4.3, 3.19, "Slow Thinking", "<SLOW>", "Self-correct via reflection before acting.", "ECFDF5");

  // Knowledgeable thinking
  outcome(s, 7.4, 3.19, "Knowledgeable Thinking", "<KNOW>", "Retrieve external knowledge — only when truly needed.", "FFFBEB");
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 4: KnowSelf Framework Pipeline
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  addTitle(s, "KnowSelf Framework: Data Construction → Two-Stage Training → Self-Aware Inference", C.navy);
  addFooter(s);

  const steps = [
    {
      num: "01",
      title: "Self-Awareness Data Construction",
      bullets: [
        "Agent self-explores environments without supervision",
        "Heuristic criterion labels each step:",
        "  · Predicted = Gold → Fast",
        "  · Reflection fixes it → Slow",
        "  · Neither works → Knowledgeable",
        "Special tokens inserted into trajectory data",
      ]
    },
    {
      num: "02",
      title: "Two-Stage Training",
      bullets: [
        "Stage 1 — SFT:",
        "  Teaches initial self-awareness patterns from labeled data",
        "Stage 2 — RPO (Reward-based Policy Optimization):",
        "  Refines special-token generation accuracy",
        "  Reward based on correct situation identification",
      ]
    },
    {
      num: "03",
      title: "Self-Aware Inference",
      bullets: [
        "Agent generates situation tokens at each step",
        "<FAST> → execute direct action",
        "<SLOW> → trigger self-reflection loop",
        "<KNOW> → query external knowledge base",
        "Selective retrieval: only ~15–26% of steps need knowledge",
      ]
    },
  ];

  steps.forEach((st, i) => {
    const x = 0.25 + i * 3.22;
    const cardW = 3.08;
    s.addShape(pres.shapes.RECTANGLE, {
      x, y: 0.88, w: cardW, h: 4.22,
      fill: { color: C.white }, line: { color: C.navy, width: 1 },
      shadow: makeShadow()
    });
    // Number badge
    s.addShape(pres.shapes.OVAL, {
      x: x + 0.1, y: 0.94, w: 0.58, h: 0.58,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    s.addText(st.num, {
      x: x + 0.1, y: 0.94, w: 0.58, h: 0.58,
      fontSize: 14, bold: true, color: C.white, align: "center", valign: "middle", margin: 0
    });
    s.addText(st.title, {
      x: x + 0.76, y: 0.96, w: cardW - 0.86, h: 0.56,
      fontSize: 12, bold: true, color: C.dark2, margin: 0
    });
    // Divider
    s.addShape(pres.shapes.LINE, {
      x: x + 0.1, y: 1.58, w: cardW - 0.2, h: 0,
      line: { color: C.tealLt, width: 1 }
    });
    // Bullets
    const bulletItems = st.bullets.map((b, bi) => ({
      text: b,
      options: { fontSize: 10.5, color: C.dark2, bullet: b.startsWith("  ·") ? false : true, breakLine: bi < st.bullets.length - 1 }
    }));
    s.addText(bulletItems, {
      x: x + 0.15, y: 1.65, w: cardW - 0.25, h: 3.35,
      valign: "top", margin: 0
    });

    // Arrow between cards
    if (i < 2) {
      s.addShape(pres.shapes.LINE, {
        x: x + cardW, y: 3.0, w: 0.14, h: 0,
        line: { color: C.teal, width: 2 }
      });
    }
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 5: Qualitative Examples
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  addTitle(s, "KnowSelf Correctly Heats a Mug and Places a Saltshaker Where Baselines Fail", C.dark);
  addFooter(s);

  // Left example
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.25, y: 0.88, w: 4.6, h: 4.22,
    fill: { color: C.white }, line: { color: C.navy, width: 1 }, shadow: makeShadow()
  });
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.25, y: 0.88, w: 4.6, h: 0.42,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  s.addText('Task A: "Put a hot mug in cabinet"', {
    x: 0.35, y: 0.88, w: 4.4, h: 0.42,
    fontSize: 12, bold: true, color: C.white, valign: "middle", margin: 0
  });

  s.addText("OpenAI-O1 (Baseline):", {
    x: 0.35, y: 1.38, w: 4.3, h: 0.3,
    fontSize: 11, bold: true, color: "DC2626", margin: 0
  });
  s.addText([
    { text: "✗ Opens microwave — then incorrectly tries to take an ", options: { breakLine: false } },
    { text: "egg", options: { bold: true, breakLine: false } },
    { text: " from it.\n  Misidentifies the object; task fails.", options: {} }
  ], {
    x: 0.35, y: 1.68, w: 4.3, h: 0.85,
    fontSize: 10.5, color: C.dark2, margin: 0
  });

  s.addShape(pres.shapes.LINE, { x: 0.35, y: 2.62, w: 4.3, h: 0, line: { color: C.mint, width: 1 } });

