    { text: "Backbone", options: { bold: true, fill: { color: C.navy }, color: C.white, fontSize: 9, align: "center" } },
    { text: "Method",   options: { bold: true, fill: { color: C.navy }, color: C.white, fontSize: 9, align: "center" } },
    { text: "Know%",    options: { bold: true, fill: { color: C.navy }, color: C.white, fontSize: 9, align: "center" } },
    { text: "Put",      options: { bold: true, fill: { color: C.navy }, color: C.white, fontSize: 9, align: "center" } },
