    { text: "Cool",     options: { bold: true, fill: { color: C.navy }, color: C.white, fontSize: 9, align: "center" } },
    { text: "Examine",  options: { bold: true, fill: { color: C.navy }, color: C.white, fontSize: 9, align: "center" } },
