    { text: "All",      options: { bold: true, fill: { color: C.navy }, color: C.white, fontSize: 9, align: "center" } },
  ];

  function mkCell(text, bold, bg, color) {
    return { text: String(text), options: { fontSize: 8.5, align: "center", bold: !!bold, fill: bg ? { color: bg } : undefined, color: color || C.dark2 } };
  }
  function mkRow(backbone, method, know, put, clean, heat, cool, examine, putTwo, all, highlight) {
    const bg = highlight ? "CCFBF1" : undefined;
    const c  = highlight ? C.dark  : C.dark2;
    return [
      mkCell(backbone, highlight, bg, c),
      mkCell(method,   highlight, bg, c),
      mkCell(know,     highlight, highlight ? "0D9488" : undefined, highlight ? C.white : (know === "100%" ? "DC2626" : C.dark2)),
      mkCell(put,      highlight, bg, c),
      mkCell(clean,    highlight, bg, c),
      mkCell(heat,     highlight, bg, c),
      mkCell(cool,     highlight, bg, c),
      mkCell(examine,  highlight, bg, c),
      mkCell(putTwo,   highlight, bg, c),
      mkCell(all,      highlight, bg, highlight ? C.teal : C.dark2),
    ];
  }

  const rows = [
    hdr,
    mkRow("GPT-4o",    "ReAct",     "0%",     "83.33", "74.19", "69.57", "85.71", "77.78", "64.71", "76.12"),
    mkRow("GPT-4o",    "Reflexion", "0%",     "100.00","87.10", "73.91", "90.48", "83.33", "70.59", "85.07"),
