{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  addTitle(s, "Minimal Knowledge, Maximum Impact: KnowSelf's Efficiency Advantage", C.dark);
  addFooter(s);

  // Overall accuracy bar chart (left)
  const accLabels = ["ReAct\n(GPT-4o)", "Reflexion\n(GPT-4o)", "ExpeL\n(GPT-4o)", "ETO\n(Llama)", "KnowAgent\n(Llama)", "WKM\n(Llama)", "KnowSelf\n(Llama)", "ETO\n(Gemma)", "KnowAgent\n(Gemma)", "WKM\n(Gemma)", "KnowSelf\n(Gemma)"];
  const accValues = [76.12, 85.07, 79.85, 78.36, 75.37, 77.61, 84.33, 71.64, 73.88, 76.12, 79.85];
  const accColors = ["64748B","64748B","64748B","94A3B8","94A3B8","94A3B8","0D9488","B0BEC5","B0BEC5","B0BEC5","14B8A6"];

