    { num: "5", text: "The paradigm generalizes across model scales: even Gemma-2B reaches 79.85%, matching GPT-4o ExpeL without using a frontier model." },
  ];

  takeaways.forEach((t, i) => {
    const y = 1.3 + i * 0.77;
    s.addShape(pres.shapes.OVAL, {
      x: 0.4, y: y + 0.04, w: 0.42, h: 0.42,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    s.addText(t.num, {
      x: 0.4, y: y + 0.04, w: 0.42, h: 0.42,
      fontSize: 13, bold: true, color: C.white, align: "center", valign: "middle", margin: 0
    });
    s.addText(t.text, {
      x: 0.95, y, w: 8.7, h: 0.7,
      fontSize: 11.5, color: "E2E8F0", valign: "middle", margin: 0
    });
  });

  // Bottom bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.45, w: 10, h: 0.175,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  s.addText("arxiv.org/abs/2504.03553", {
    x: 0.4, y: 5.44, w: 9, h: 0.18,
    fontSize: 9, color: C.white, valign: "middle", margin: 0
  });
}

// ── Write file ───────────────────────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("✓ Saved /app/output/final_deck.pptx"))
  .catch(e => { console.error(e); process.exit(1); });

