    showValue: true, dataLabelFontSize: 7, dataLabelColor: "1E293B",
    showLegend: false,
    showTitle: true, title: "Overall Accuracy (%) by Method", titleFontSize: 10, titleColor: C.dark2,
  });

  const knowLabels = ["ExpeL", "KnowAgent", "WKM", "KnowSelf\n(Gemma)", "KnowSelf\n(Llama)"];
  const knowValues = [100, 100, 100, 26.41, 15.01];
  const knowColors = ["DC2626","DC2626","DC2626","14B8A6","0D9488"];

  s.addChart(pres.charts.BAR, [{ name: "Knowledge Usage (%)", labels: knowLabels, values: knowValues }], {
    x: 6.1, y: 0.82, w: 3.65, h: 3.75, barDir: "col",
    chartColors: knowColors,
    chartArea: { fill: { color: C.white }, roundedCorners: false },
    catAxisLabelColor: "475569", catAxisLabelFontSize: 8,
    valAxisLabelColor: "475569", valAxisLabelFontSize: 8,
    valAxisMinVal: 0, valAxisMaxVal: 110,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true, dataLabelFontSize: 8, dataLabelColor: "1E293B",
    dataLabelPosition: "inEnd",
    showLegend: false,
    showTitle: true, title: "Knowledge Usage (%) by Method", titleFontSize: 10, titleColor: C.dark2,
  });

  s.addText("KnowSelf uses only 15–26% knowledge queries yet achieves the highest accuracy among open-weight models — beating methods that always retrieve knowledge (100%).", {
    x: 0.25, y: 4.68, w: 9.5, h: 0.58,
    fontSize: 10.5, color: C.dark2, italic: true, margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 8: Key Takeaways
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.dark };

  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.18, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal }
  });

  s.addText("Key Takeaways", {
    x: 0.38, y: 0.18, w: 9.2, h: 0.56,
    fontSize: 28, bold: true, color: C.white, fontFace: "Calibri", margin: 0
  });
  s.addText("Self-Awareness Is the Missing Piece in Agent Planning", {
    x: 0.38, y: 0.72, w: 9.2, h: 0.34,
    fontSize: 13.5, color: C.tealLt, italic: true, margin: 0
  });

  const takeaways = [
    "Indiscriminate knowledge injection (flood irrigation) is wasteful — using 100% knowledge can hurt more than it helps.",
    "Agents can learn situational self-awareness via lightweight heuristic labeling and special tokens — no expensive annotation needed.",
    "KnowSelf (Llama-8B) achieves 84.33% on ALFWorld, outperforming GPT-4o ReAct (76.12%) and GPT-4o ExpeL (79.85%).",
    "Only 15–26% of steps require external knowledge, vs. 100% for KnowAgent / WKM / ExpeL — a 4–7× reduction in retrieval cost.",
    "Generalizes across scales: Gemma-2B reaches 79.85%, matching GPT-4o ExpeL — no frontier model required.",
  ];

  takeaways.forEach((t, i) => {
    const y = 1.18 + i * 0.82;
    s.addShape(pres.shapes.OVAL, {
      x: 0.38, y: y + 0.06, w: 0.4, h: 0.4,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    s.addText(String(i + 1), {
      x: 0.38, y: y + 0.06, w: 0.4, h: 0.4,
      fontSize: 12, bold: true, color: C.white, align: "center", valign: "middle", margin: 0
    });
    s.addText(t, {
      x: 0.9, y, w: 8.82, h: 0.75,
      fontSize: 11.5, color: "E2E8F0", valign: "middle", margin: 0
    });
  });

  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.45, w: 10, h: 0.175,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  s.addText("KnowSelf  ·  arxiv.org/abs/2504.03553", {
    x: 0.4, y: 5.44, w: 9, h: 0.18,
    fontSize: 9, color: C.white, valign: "middle", margin: 0
  });
}

pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
