"use strict";
const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "KnowSelf: Teaching LLM Agents When to Think, Reflect, or Seek Knowledge";

const C = {
  dark:    "0D1B2A",
  navy:    "1B3A5C",
  teal:    "0D9488",
  tealLt:  "14B8A6",
  mint:    "CCFBF1",
  white:   "FFFFFF",
  offWhite:"F8FAFC",
  lightBg: "EFF6FF",
  slate:   "64748B",
  dark2:   "1E293B",
  gold:    "F59E0B",
  goldLt:  "FEF9C3",
};

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.10 });

function addTitle(slide, text, bg) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.72,
    fill: { color: bg || C.navy }, line: { color: bg || C.navy }
  });
  slide.addText(text, {
    x: 0.4, y: 0, w: 9.2, h: 0.72,
    fontSize: 20, bold: true, color: C.white,
    valign: "middle", margin: 0
  });
}

function addFooter(slide) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.45, w: 10, h: 0.175,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  slide.addText("KnowSelf  ·  arxiv.org/abs/2504.03553", {
    x: 0.4, y: 5.44, w: 9, h: 0.18,
    fontSize: 9, color: C.white, valign: "middle", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 1: Title
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.dark };

  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.18, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal }
  });

  s.addText("KnowSelf", {
    x: 0.45, y: 0.55, w: 9, h: 1.0,
    fontSize: 52, bold: true, color: C.white, fontFace: "Calibri"
  });
  s.addText("Agentic Knowledgeable Self-Awareness\nfor LLM-Based Agents", {
    x: 0.45, y: 1.52, w: 8.5, h: 0.9,
    fontSize: 22, color: C.tealLt, fontFace: "Calibri"
  });

  // Tagline card
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.45, y: 2.65, w: 9.1, h: 1.1,
    fill: { color: C.navy }, line: { color: C.teal, width: 1.5 }
  });
  s.addText("Enabling agents to autonomously decide when to act directly,\nself-reflect, or consult external knowledge — only when needed.", {
    x: 0.6, y: 2.7, w: 8.8, h: 1.0,
    fontSize: 14, color: C.mint, italic: true, valign: "middle", margin: 0
  });

  // Three pillars row
  const pillars = ["Fast Thinking", "Slow Thinking", "Knowledgeable Thinking"];
  const pColors = ["0369A1", "0D9488", "D97706"];
  pillars.forEach((p, i) => {
    const x = 0.45 + i * 3.05;
    s.addShape(pres.shapes.RECTANGLE, {
      x, y: 4.05, w: 2.85, h: 0.72,
      fill: { color: pColors[i] }, line: { color: pColors[i] }
    });
    s.addText(p, {
      x, y: 4.05, w: 2.85, h: 0.72,
      fontSize: 13, bold: true, color: C.white, align: "center", valign: "middle", margin: 0
    });
  });

  // Reference
  s.addText("arxiv.org/abs/2504.03553", {
    x: 0.45, y: 4.98, w: 4, h: 0.3,
    fontSize: 11, color: "7ECFF5"
  });

  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.45, w: 10, h: 0.175,
    fill: { color: C.teal }, line: { color: C.teal }
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 2: Problem
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  addTitle(s, "Current Agent Training Uses 'Flood Irrigation' — Indiscriminate Knowledge Injection");
  addFooter(s);

  const cards = [
    { label: "① Trajectory Imitation", sub: "ReAct-style", desc: "Blindly mimics gold trajectories.\nFragile on unexpected inputs." },
    { label: "② Trial-and-Error Refinement", sub: "Reflexion-style", desc: "External feedback injected at\nevery step regardless of need." },
    { label: "③ Knowledge-Augmented Planning", sub: "KnowAgent / WKM", desc: "Domain knowledge always prepended —\n100% of steps, unconditionally." },
  ];

  cards.forEach((c, i) => {
    const x = 0.32 + i * 3.13;
    s.addShape(pres.shapes.RECTANGLE, {
      x, y: 0.88, w: 3.0, h: 2.0,
      fill: { color: C.lightBg }, line: { color: C.navy, width: 1 },
      shadow: makeShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x, y: 0.88, w: 3.0, h: 0.12,
      fill: { color: C.navy }, line: { color: C.navy }
    });
    s.addText(c.label, {
      x: x + 0.1, y: 1.0, w: 2.8, h: 0.36,
      fontSize: 12, bold: true, color: C.dark2, margin: 0
    });
    s.addText(c.sub, {
      x: x + 0.1, y: 1.36, w: 2.8, h: 0.26,
      fontSize: 10.5, color: C.teal, italic: true, margin: 0
    });
    s.addText(c.desc, {
      x: x + 0.1, y: 1.62, w: 2.8, h: 1.0,
      fontSize: 11, color: C.dark2, margin: 0
    });
  });

  // Result banner
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.32, y: 3.1, w: 9.36, h: 0.65,
    fill: { color: C.goldLt }, line: { color: C.gold, width: 1.5 }
  });
  s.addText("Result: Wasteful inference, pattern collapse, and suboptimal performance on novel inputs.", {
    x: 0.48, y: 3.13, w: 9.04, h: 0.58,
    fontSize: 13, bold: true, color: "92400E", valign: "middle", margin: 0
  });

  // Human contrast box
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.32, y: 3.92, w: 9.36, h: 1.0,
    fill: { color: C.mint }, line: { color: C.teal, width: 1 }
  });
  s.addText("Humans use situational self-awareness — assessing whether to act directly, pause and reflect, or seek outside help. KnowSelf brings this metacognitive ability to LLM agents.", {
    x: 0.5, y: 3.98, w: 9.0, h: 0.88,
    fontSize: 12.5, color: C.dark2, valign: "middle", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 3: Three Thinking Modes (Flow Diagram)
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  addTitle(s, "Three Situational Modes: Fast Thinking, Slow Thinking, and Knowledgeable Thinking", C.dark);
  addFooter(s);

  // Start node
  s.addShape(pres.shapes.RECTANGLE, {
    x: 3.6, y: 0.85, w: 2.8, h: 0.5,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  s.addText("Agent at Decision Step", {
    x: 3.6, y: 0.85, w: 2.8, h: 0.5,
    fontSize: 12, bold: true, color: C.white, align: "center", valign: "middle", margin: 0
  });

  // Arrow down
  s.addShape(pres.shapes.LINE, { x: 5.0, y: 1.35, w: 0, h: 0.32, line: { color: C.slate, width: 1.5 } });

  // Q1 box
  s.addShape(pres.shapes.RECTANGLE, {
    x: 3.1, y: 1.67, w: 3.8, h: 0.5,
    fill: { color: C.teal }, line: { color: C.navy, width: 1 }
  });
  s.addText("Predicted action = Gold?", {
    x: 3.1, y: 1.67, w: 3.8, h: 0.5,
    fontSize: 12, bold: true, color: C.white, align: "center", valign: "middle", margin: 0
  });

  // YES branch (left)
  s.addShape(pres.shapes.LINE, { x: 3.1, y: 1.92, w: -1.5, h: 0, line: { color: "0369A1", width: 1.5 } });
  s.addShape(pres.shapes.LINE, { x: 1.6, y: 1.92, w: 0, h: 0.92, line: { color: "0369A1", width: 1.5 } });
  s.addText("YES", { x: 1.7, y: 1.74, w: 0.7, h: 0.25, fontSize: 10, color: "0369A1", bold: true, margin: 0 });

  // NO branch (right) — keep within slide bounds
  s.addShape(pres.shapes.LINE, { x: 6.9, y: 1.92, w: 1.25, h: 0, line: { color: C.slate, width: 1.5 } });
  s.addShape(pres.shapes.LINE, { x: 8.15, y: 1.92, w: 0, h: 0.36, line: { color: C.slate, width: 1.5 } });
  s.addText("NO", { x: 6.95, y: 1.74, w: 0.5, h: 0.25, fontSize: 10, color: C.slate, bold: true, margin: 0 });

  // Q2 box — right branch
  s.addShape(pres.shapes.RECTANGLE, {
    x: 6.55, y: 2.28, w: 3.2, h: 0.5,
    fill: { color: C.slate }, line: { color: C.navy, width: 1 }
  });
  s.addText("Reflection fixes it?", {
    x: 6.55, y: 2.28, w: 3.2, h: 0.5,
    fontSize: 12, bold: true, color: C.white, align: "center", valign: "middle", margin: 0
  });

  // YES from Q2 → Slow
  s.addShape(pres.shapes.LINE, { x: 6.55, y: 2.53, w: -1.5, h: 0, line: { color: C.tealLt, width: 1.5 } });
  s.addShape(pres.shapes.LINE, { x: 5.05, y: 2.53, w: 0, h: 0.65, line: { color: C.tealLt, width: 1.5 } });
  s.addText("YES", { x: 4.65, y: 2.36, w: 0.65, h: 0.25, fontSize: 10, color: C.tealLt, bold: true, margin: 0 });

  // NO from Q2 → Knowledgeable (down, within bounds)
  s.addShape(pres.shapes.LINE, { x: 8.15, y: 2.78, w: 0, h: 0.45, line: { color: C.gold, width: 1.5 } });
  s.addText("NO", { x: 8.2, y: 2.6, w: 0.5, h: 0.25, fontSize: 10, color: C.gold, bold: true, margin: 0 });

  // Outcome boxes
  const outcomeH = 1.52;
  function outcome(slide, x, y, title, token, desc, fillColor, accentColor) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 2.85, h: outcomeH,
      fill: { color: fillColor }, line: { color: accentColor, width: 1.5 },
      shadow: makeShadow()
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 2.85, h: 0.1,
      fill: { color: accentColor }, line: { color: accentColor }
    });
    slide.addText(title, {
      x: x + 0.1, y: y + 0.12, w: 2.65, h: 0.35,
      fontSize: 13, bold: true, color: C.dark2, margin: 0
    });
    slide.addText("Token: " + token, {
      x: x + 0.1, y: y + 0.47, w: 2.65, h: 0.28,
      fontSize: 11, color: accentColor, italic: true, bold: true, margin: 0
    });
    slide.addText(desc, {
      x: x + 0.1, y: y + 0.78, w: 2.65, h: 0.68,
      fontSize: 10.5, color: C.dark2, margin: 0
    });
  }

  outcome(s, 0.2,  3.18, "Fast Thinking",          "<FAST>", "Direct correct action — no extra computation.", "DBEAFE", "0369A1");
  outcome(s, 3.58, 3.18, "Slow Thinking",           "<SLOW>", "Self-correct via reflection before acting.",    "DCFCE7", C.teal);
  outcome(s, 6.95, 3.18, "Knowledgeable Thinking",  "<KNOW>", "Retrieve external knowledge — only when truly needed.", "FEF9C3", C.gold);
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 4: KnowSelf Framework Pipeline
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  addTitle(s, "KnowSelf Framework: Data Construction → Two-Stage Training → Self-Aware Inference", C.navy);
  addFooter(s);

  const steps = [
    {
      num: "01",
      title: "Self-Awareness Data Construction",
      items: [
        "Agent self-explores environments",
        "Heuristic labels each step:",
        "  Predicted = Gold → <FAST>",
        "  Reflection fixes it → <SLOW>",
        "  Neither works → <KNOW>",
        "Special tokens inserted into trajectory",
      ]
    },
    {
      num: "02",
      title: "Two-Stage Training",
      items: [
        "Stage 1 — Supervised Fine-Tuning (SFT):",
        "  Learns initial self-awareness patterns",
        "Stage 2 — RPO (Reward-based Policy Optimization):",
        "  Refines special-token generation",
        "  Reward based on correct situation ID",
        "  No expensive human annotation needed",
      ]
    },
    {
      num: "03",
      title: "Self-Aware Inference",
      items: [
        "Agent generates situation token each step",
        "<FAST> → execute direct action",
        "<SLOW> → trigger self-reflection loop",
        "<KNOW> → query external knowledge base",
        "Result: only ~15–26% of steps query",
        "  external knowledge",
      ]
    },
  ];

  steps.forEach((st, i) => {
    const x = 0.28 + i * 3.22;
    const cardW = 3.08;
    s.addShape(pres.shapes.RECTANGLE, {
      x, y: 0.88, w: cardW, h: 4.2,
      fill: { color: C.white }, line: { color: C.navy, width: 1 },
      shadow: makeShadow()
    });
    s.addShape(pres.shapes.OVAL, {
      x: x + 0.12, y: 0.96, w: 0.56, h: 0.56,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    s.addText(st.num, {
      x: x + 0.12, y: 0.96, w: 0.56, h: 0.56,
      fontSize: 14, bold: true, color: C.white, align: "center", valign: "middle", margin: 0
    });
    s.addText(st.title, {
      x: x + 0.76, y: 0.98, w: cardW - 0.88, h: 0.55,
      fontSize: 11.5, bold: true, color: C.dark2, margin: 0
    });
    s.addShape(pres.shapes.LINE, {
      x: x + 0.1, y: 1.6, w: cardW - 0.2, h: 0,
      line: { color: C.tealLt, width: 0.75 }
    });

    const bulletItems = st.items.map((b, bi) => ({
      text: b,
      options: {
        fontSize: 10.5,
        color: b.startsWith("  ") ? C.slate : C.dark2,
        bullet: b.startsWith("  ") ? false : true,
        breakLine: bi < st.items.length - 1
      }
    }));
    s.addText(bulletItems, {
      x: x + 0.15, y: 1.68, w: cardW - 0.28, h: 3.32,
      valign: "top", margin: 0
    });

    if (i < 2) {
      s.addShape(pres.shapes.LINE, {
        x: x + cardW + 0.02, y: 2.98, w: 0.18, h: 0,
        line: { color: C.teal, width: 2 }
      });
    }
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 5: Qualitative Examples
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.offWhite };
  addTitle(s, "KnowSelf Correctly Heats a Mug and Places a Saltshaker Where Baselines Fail", C.dark);
  addFooter(s);

  function exCard(slide, x, taskLabel, baseline, baselineDesc, ksDesc, tokenText, tokenColor) {
    const w = 4.65;
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: 0.88, w, h: 4.2,
      fill: { color: C.white }, line: { color: C.navy, width: 1 }, shadow: makeShadow()
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: 0.88, w, h: 0.42,
      fill: { color: C.navy }, line: { color: C.navy }
    });
    slide.addText(taskLabel, {
      x: x + 0.1, y: 0.88, w: w - 0.2, h: 0.42,
      fontSize: 11.5, bold: true, color: C.white, valign: "middle", margin: 0
    });

    // Baseline section
    slide.addShape(pres.shapes.RECTANGLE, {
      x: x + 0.1, y: 1.42, w: w - 0.2, h: 0.28,
      fill: { color: "FEE2E2" }, line: { color: "FCA5A5", width: 0.5 }
    });
    slide.addText(baseline + " (Baseline)  ✗", {
      x: x + 0.15, y: 1.42, w: w - 0.3, h: 0.28,
      fontSize: 10.5, bold: true, color: "DC2626", valign: "middle", margin: 0
    });
    slide.addText(baselineDesc, {
      x: x + 0.15, y: 1.74, w: w - 0.3, h: 1.0,
      fontSize: 10.5, color: C.dark2, margin: 0
    });

    slide.addShape(pres.shapes.LINE, {
      x: x + 0.15, y: 2.85, w: w - 0.3, h: 0,
      line: { color: "D1D5DB", width: 0.75 }
    });

    // KnowSelf section
    slide.addShape(pres.shapes.RECTANGLE, {
      x: x + 0.1, y: 2.98, w: w - 0.2, h: 0.28,
      fill: { color: "D1FAE5" }, line: { color: "6EE7B7", width: 0.5 }
    });
    slide.addText("KnowSelf (Llama-8B)  ✓", {
      x: x + 0.15, y: 2.98, w: w - 0.3, h: 0.28,
      fontSize: 10.5, bold: true, color: "065F46", valign: "middle", margin: 0
    });
    slide.addText([
      { text: "Generates ", options: { breakLine: false } },
      { text: tokenText, options: { bold: true, color: tokenColor, breakLine: false } },
      { text: " token — " + ksDesc, options: {} }
    ], {
      x: x + 0.15, y: 3.3, w: w - 0.3, h: 1.65,
      fontSize: 10.5, color: C.dark2, margin: 0
    });
  }

  exCard(s, 0.25,
    'Task A: "Put a hot mug in cabinet"',
    "OpenAI-O1",
    "Opens microwave — then incorrectly tries to take an egg from it. Misidentifies the object; task fails.",
    "realizes it should heat the mug using the already-open microwave. Task succeeds.",
    "<SLOW>  Reflection", C.teal
  );

